ADMIN only. Returns MRR, subscriber tiles, plan distribution, and KPI metrics.

Example 200:
{
  "data": {
    "mrr": { "amount_sar": 54200, "change_pct": 12.4, "change_direction": "up", "comparison_label": "vs last month" },
    "subscriber_counts": { "active": 248, "new_today": 14, "churned": 3 },
    "subscribers_by_plan": [{ "plan_id": "month", "plan_label": "Month", "count": 129 }],
    "key_metrics": { "avg_skip_rate": { "value": 1.4, "change": 0.2, "change_direction": "up", "comparison_label": "vs last week" }, "salad_meal_pct": { "value": 34, "label": "of active subs" } },
    "as_of": "2026-09-17T12:00:00Z"
  }
}

